/* ---------------------------------------------------------------- calls */
const pick = (a) => a[Math.floor(Math.random() * a.length)];

async function callTool(env, name, args) {
  const ix = await index(env);

  switch (name) {
    case 'families':
      return ix.families.map((f) => ({
        id: f.id, label: f.label, deva: f.deva, gender: f.gender,
        colour: f.colour, stems: f.stems.length, note: f.note,
      }));

    case 'cases': {
      const k = await cases(env);
      return {
        vibhakti: ix.vibhakti.map((v) => ({ id: v.id, name: v.sanskrit, deva: v.deva, en: v.en, question: v.question, sutra: v.sutra })),
        karaka: k.karaka.map((o) => ({ id: o.id, label: o.label, en: o.en, gloss: o.gloss, wears: o.vibhakti, sutra: o.sutra })),
      };
    }

    case 'stems':
      return ix.stems
        .filter((s) => !args.family || s.family === args.family)
        .map((s) => {
          const f = ix.families.find((x) => x.id === s.family);
          return { id: s.id, deva: s.deva, iast: s.iast, gloss: s.gloss, family: s.family, gender: s.gender, colour: f.colour };
        });

    case 'paradigm': {
      const s = ix.stems.find((x) => x.id === args.stem);
      if (!s) throw new Error(`unknown stem ${args.stem}`);
      const doc = await family(env, s.family);
      const p = doc.stems[s.id].paradigm;
      const out = { stem: s.iast, deva: s.deva, gloss: s.gloss, family: s.family, forms: {} };
      for (const [vib, row] of Object.entries(p)) {
        out.forms[vib] = {};
        for (const [vac, c] of Object.entries(row)) {
          out.forms[vib][vac] = c.status === 'DERIVED' ? { iast: c.iast, deva: c.deva } : { blocked: true };
        }
      }
      return out;
    }

    case 'form': {
      const slot = await nounSlot(env, args);
      return slot;
    }

    case 'check': {
      const slot = await nounSlot(env, args);
      const a = low(args.answer);
      const verdict = a === low(slot.iast) ? 'exact'
        : (bare(args.answer) && bare(args.answer) === bare(slot.iast)) ? 'close'
        : 'wrong';
      return { verdict, correct: slot.iast, deva: slot.deva, family: slot.family, colour: slot.colour,
               steps: slot.steps, hint: verdict === 'wrong' ? 'check the stem family and the sup ending' : null };
    }

    case 'parse': {
      const ix2 = await index(env);
      const s = ix2.stems.find((x) => x.id === args.stem || x.iast === low(args.stem));
      if (!s) throw new Error(`unknown stem ${args.stem}`);
      const vib = vibOf(ix2, args.case);
      const vac = vacOf(ix2, args.number);
      if (!vib) throw new Error(`unknown case ${args.case}`);
      if (!vac) throw new Error(`unknown number ${args.number}`);
      const doc = await family(env, s.family);
      const analyses = [];
      for (const [v2, row] of Object.entries(doc.stems[s.id].paradigm))
        for (const [w2, cc] of Object.entries(row))
          if (cc.status === 'DERIVED' && low(cc.iast) === low(args.form)) analyses.push(`${v2}.${w2}`);
      if (!analyses.length) throw new Error(`${args.form} is not a form of ${s.iast}`);
      const ok = analyses.some((a) => a === `${vib.id}.${vac.id}`);
      const f = ix2.families.find((x) => x.id === s.family);
      return { verdict: ok ? 'valid' : 'invalid', form: args.form,
               claimed: `${vib.en} ${vac.en}`,
               valid_analyses: analyses, colour: f.colour };
    }

    case 'tenses': {
      const v = await verbs(env);
      return {
        lakara: v.lakara,
        purusha: v.purusha,
        vacana: v.vacana,
        roots: v.roots,
        counts: v.counts,
      };
    }

    case 'verb': {
      const slot = await verbSlot(env, args);
      return slot;
    }

    case 'verb_check': {
      const slot = await verbSlot(env, args);
      const a = low(args.answer);
      const verdict = a === low(slot.iast) ? 'exact'
        : (bare(args.answer) && bare(args.answer) === bare(slot.iast)) ? 'close'
        : 'wrong';
      return { verdict, correct: slot.iast, deva: slot.deva, tense: slot.tense, colour: slot.colour,
               steps: slot.steps };
    }

    case 'curriculum': {
      const c = await curriculum(env);
      const stages = c.stages
        .filter((x) => !args.track || x.track === args.track)
        .map((x, i) => ({ order: i + 1, ...x }));
      return { pass: c.pass, note: c.note, stages };
    }

    case 'attested': {
      const a = await attested(env);
      return {
        warning: a.warning,
        entries: a.entries.filter((e) =>
          (!args.stem || e.stem === args.stem) &&
          (!args.case || e.vibhakti === args.case)),
      };
    }

    case 'drill': {
      const track = args.track === 'verb' ? 'verb' : 'noun';
      if (track === 'noun') {
        const fam = args.family || pick(ix.families).id;
        const stems = ix.stems.filter((s) => s.family === fam);
        const s = pick(stems.length ? stems : ix.stems);
        const doc = await family(env, s.family);
        const mode = args.mode || pick(['family', 'build', 'reverse', 'read']);
        const familyObj = ix.families.find((f) => f.id === s.family);
        if (mode === 'family') {
          const out = { track: 'noun', mode, colour: familyObj.colour,
                   prompt: `Which family does ${s.iast} (${s.gloss}) belong to?`,
                   grade: 'any label naming exactly one family; accept the id too' };
          if (args.reveal) out.answer = familyObj.label;
          return out;
        }
        const vib = pick(ix.vibhakti), vac = pick(ix.vacana);
        const c = doc.stems[s.id].paradigm[vib.id][vac.id];
        if (c.status !== 'DERIVED') return { track: 'noun', blocked: true, retry: true };
        if (mode === 'reverse' || mode === 'read') {
          const rout = { track: 'noun', mode, prompt: `Which case and number is ${c.iast} (of ${s.iast}, "${s.gloss}")?`,
                   colour: familyObj.colour,
                   check_with: 'parse',
                   args: { stem: s.id, form: c.iast, case: '__LEARNER_CASE__', number: '__LEARNER_NUMBER__' },
                   note: 'ask first; then grade with parse. Accept any valid analysis; never reveal the valid list first' };
          if (args.reveal) {
            const analyses = [];
            for (const [v2, row] of Object.entries(doc.stems[s.id].paradigm))
              for (const [w2, cc] of Object.entries(row))
                if (cc.status === 'DERIVED' && low(cc.iast) === low(c.iast)) analyses.push(`${v2}.${w2}`);
            rout.answer = analyses;
          }
          return rout;
        }
        const bout = { track: 'noun', mode: 'build',
                 prompt: `Give the ${vib.en} ${vac.en} of ${s.iast} (${s.gloss}).`,
                 colour: familyObj.colour,
                 check_with: 'check', args: { stem: s.id, case: vib.id, number: vac.id } };
        if (args.reveal) { bout.answer = c.iast; bout.deva = c.deva; }
        return bout;
      }

      const v = await verbs(env);
      const lak = args.tense ? (v.lakara.find((l) => l.id === args.tense || l.en === args.tense) || pick(v.lakara)) : pick(v.lakara);
      const root = pick(v.roots), pu = pick(v.purusha), va = pick(v.vacana);
      const c = v.paradigms[root.id][lak.id][`${pu.id}.${va.id}`];
      if (!c || c.status !== 'DERIVED') return { track: 'verb', blocked: true, retry: true };
      const mode = args.mode === 'tense' ? 'tense' : 'build';
      if (mode === 'tense') {
        const tout = { track: 'verb', mode, prompt: `Which tense is ${c.iast} (root ${root.iast}, ${pu.en} person ${va.en})?`,
                 colour: lak.colour,
                 check_with: 'name one of: present, past (imperfect), future, imperative, optative' };
        if (args.reveal) tout.answer = lak.en;
        return tout;
      }
      const vout = { track: 'verb', mode: 'build',
               prompt: `Give the ${lak.en}, ${pu.en} person ${va.en}, of root ${root.iast} (${root.gloss}).`,
               colour: lak.colour,
               check_with: 'verb_check', args: { root: root.id, tense: lak.id, person: pu.id, number: va.id } };
      if (args.reveal) { vout.answer = c.iast; vout.deva = c.deva; }
      return vout;
    }

    case 'harness':
      return {
        server: SERVER,
        what: 'Sanskrit drill trainer. Colour = the thing being learned: a noun family, or a verb tense.',
        colour_system: {
          noun: 'one colour per declension family (17)',
          verb: 'one colour per tense/lakāra (5)',
          roles: ix.colour_roles,
        },
        counts: { ...ix.counts, verb_forms: (await verbs(env)).counts.forms },
        families: ix.families.map((f) => ({ id: f.id, label: f.label, colour: f.colour, gender: f.gender })),
        cases: ix.vibhakti.map((v) => ({ id: v.id, en: v.en, question: v.question })),
        tenses: (await verbs(env)).lakara.map((l) => ({ id: l.id, en: l.en, colour: l.colour })),
        teach_with: [
          '1. Ask which family a stem belongs to (drill track=noun mode=family).',
          '2. Ask for one case+number form, let the learner type it, grade with check.',
          '3. Correct using the colour of the family and the sūtra steps returned.',
          '4. For syncretic forms (devabhyām) accept any valid analysis.',
          '5. Verbs: same loop with verbs track=verb, graded by verb_check.',
        ],
        curriculum: (await curriculum(env)).stages.map((x) => ({
          id: x.id, track: x.track, title: x.title, needs: x.needs,
        })),
        honesty: 'Every form and step is Vidyut 0.4.0 output. A derivation is a computation, not a reading. Blocked slots never render.',
      };

    default:
      throw new Error(`unknown tool ${name}`);
  }
}

async function nounSlot(env, args) {
  const ix = await index(env);
  const s = ix.stems.find((x) => x.id === args.stem || x.iast === low(args.stem));
  if (!s) throw new Error(`unknown stem ${args.stem}`);
  const vib = vibOf(ix, args.case);
  const vac = vacOf(ix, args.number);
  if (!vib) throw new Error(`unknown case ${args.case}`);
  if (!vac) throw new Error(`unknown number ${args.number}`);
  const doc = await family(env, s.family);
  const c = doc.stems[s.id].paradigm[vib.id][vac.id];
  const f = ix.families.find((x) => x.id === s.family);
  if (!c || c.status !== 'DERIVED') {
    return { blocked: true, stem: s.iast, case: vib.en, number: vac.en, family: s.family };
  }
  return {
    stem: s.iast, deva: s.deva, gloss: s.gloss,
    case: vib.en, number: vac.en, family: f.label, family_id: f.id, colour: f.colour,
    iast: c.iast, deva_form: c.deva,
    steps: c.steps.map(([code, after, role]) => ({ sutra: code, after, role, text: (ix.sutra_map || {})[code] || '' })),
  };
}

async function verbSlot(env, args) {
  const v = await verbs(env);
  const root = v.roots.find((r) => r.id === args.root || r.iast === low(args.root));
  if (!root) throw new Error(`unknown root ${args.root}`);
  const tl = low(args.tense);
  const lak = v.lakara.find((l) =>
    l.id === tl || l.en === tl || l.en.split(' ')[0] === tl ||
    (LAK_ALIAS[l.id] || []).includes(tl));
  if (!lak) throw new Error(`unknown tense ${args.tense}`);
  const pl = low(args.person);
  const pu = v.purusha.find((p) =>
    p.id === pl || p.en === pl || p.sanskrit === pl ||
    (PERSON_ALIAS[p.id] || []).includes(pl));
  if (!pu) throw new Error(`unknown person ${args.person}`);
  const va = v.vacana.find((w) => w.id === low(args.number) || w.en === low(args.number) || w.sanskrit === low(args.number));
  if (!va) throw new Error(`unknown number ${args.number}`);
  const c = v.paradigms[root.id][lak.id][`${pu.id}.${va.id}`];
  if (!c || c.status !== 'DERIVED') return { blocked: true, root: root.iast, tense: lak.en };
  const ix = await index(env);
  return {
    root: root.iast, gloss: root.gloss, tense: lak.en, tense_id: lak.id,
    person: pu.en, number: va.en, colour: lak.colour,
    iast: c.iast, deva: c.deva,
    steps: c.steps.map(([code, after, role]) => ({ sutra: code, after, role, text: (ix.sutra_map || {})[code] || '' })),
  };
}

/* ---------------------------------------------------------------- JSON-RPC */
const ok = (id, result) => ({ jsonrpc: '2.0', id, result });
const err = (id, code, message) => ({ jsonrpc: '2.0', id, error: { code, message } });

async function handle(env, msg) {
  const { id, method, params } = msg;

  if (method === 'initialize') {
    return ok(id, {
      protocolVersion: PROTOCOL,
      capabilities: { tools: { listChanged: false } },
      serverInfo: SERVER,
      instructions:
        'Sanskrit drill trainer. Colour identifies what is being learned: a noun family (17) or a verb tense (5). ' +
        'Start with harness, then drill. Grade with check / verb_check. Never reveal an answer before the learner tries. ' +
        'Every form is generated; blocked slots do not exist.',
    });
  }
  if (method === 'notifications/initialized' || method === 'initialized') return null;
  if (method === 'ping') return ok(id, {});
  if (method === 'tools/list') return ok(id, { tools: TOOLS });

  if (method === 'tools/call') {
    const name = params?.name;
    const args = params?.arguments || {};
    if (!TOOLS.some((t) => t.name === name)) return err(id, -32602, `unknown tool ${name}`);
    try {
      const out = await callTool(env, name, args);
      return ok(id, {
        content: [{ type: 'text', text: JSON.stringify(out, null, 2) }],
        structuredContent: out,
        isError: false,
      });
    } catch (e) {
      return ok(id, {
        content: [{ type: 'text', text: `Error: ${e.message}` }],
        isError: true,
      });
    }
  }
  return err(id, -32601, `unknown method ${method}`);
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (url.pathname !== '/mcp' && url.pathname !== '/mcp/') {
      return env.ASSETS.fetch(request);
    }

    if (request.method === 'OPTIONS') {
      return new Response(null, { status: 204, headers: CORS });
    }
    if (request.method === 'GET') {
      return new Response(JSON.stringify({ error: 'use POST for MCP' }), {
        status: 405,
        headers: { ...CORS, 'Content-Type': 'application/json', Allow: 'POST, OPTIONS' },
      });
    }
    if (request.method !== 'POST') {
      return new Response('method not allowed', { status: 405, headers: CORS });
    }

    let body;
    try { body = await request.json(); } catch {
      return new Response(JSON.stringify(err(null, -32700, 'parse error')), {
        status: 400, headers: { ...CORS, 'Content-Type': 'application/json' },
      });
    }

    const messages = Array.isArray(body) ? body : [body];
    const out = [];
    for (const m of messages) {
      const r = await handle(env, m);
      if (r) out.push(r);
    }
    if (!out.length) return new Response(null, { status: 202, headers: CORS });

    return new Response(JSON.stringify(out.length === 1 ? out[0] : out), {
      status: 200,
      headers: {
        ...CORS,
        'Content-Type': 'application/json',
        'MCP-Protocol-Version': PROTOCOL,
      },
    });
  },
};
